def kronecker_conflicts(P,O):
 d={};conf=[]
 for r in range(O.shape[0]):
  for c in range(O.shape[1]):
   a,b=P[(r//3)%3,(c//3)%3],P[r%3,c%3]
   key=(int(a),int(b));v=int(O[r,c])
   if key in d and d[key]!=v:conf.append((r,c,key,d[key],v))
   d[key]=v
